function managers(){const owners=Object.keys(SHOP.owners);return '<p class="eyebrow">Team duties · your Build Your Business roles</p><h2>A real job for every owner.</h2><p>'+(CAFE?'The original packet names Olivia as Business Manager, Kaylee as Money Manager, Alyssa as Marketing Manager and Jocquan as Operations Manager. Their workday stations build on those jobs.':PET?'Max and Jaden can share every station. These suggested workday duties give each owner a clear starting point.':'Assign supply and budgeting work to your team. Existing business features stay available from the interview/shop link.')+'</p><section class="card"><div class="row spread"><h3>Shop controls</h3><button data-do="toggle-open" class="'+(s.open?'quiet':'')+'">'+(s.open?'Close new orders':'Open the shop')+'</button></div><div class="row"><label>Worker<select id="assign-person">'+owners.map(n=>'<option>'+esc(n)+'</option>').join('')+'</select></label><label>Station<select id="assign-station">'+roles.concat(['Cleanup','Pickup']).map(n=>'<option>'+n+'</option>').join('')+'</select></label><button data-do="assign">Assign duty</button></div><p>'+Object.entries(s.assignments).map(([station,person])=>'<span class="pill">'+esc(station)+': '+esc(person)+'</span>').join(' ')+'</p><div class="row"><button class="quiet" data-do="interviews">🎤 Review applicants & interview</button><button class="quiet" data-nav="inventory">📦 Check supplies</button><button class="quiet" data-nav="report">🧾 Review the workday</button></div></section><div class="grid">'+owners.map(name=>{const d=DUTIES[name]||{title:SHOP.owners[name],intro:'Supply-room responsibilities for this owner.',tasks:['Count the current supplies.','Plan a purchase within the business budget.','Place a repeat supply order and check the receipt.']};return '<section class="card role-card"><p class="eyebrow">'+esc(name)+'</p><h3>'+esc(d.title)+'</h3><p class="small">'+esc(d.intro)+'</p>'+d.tasks.map((task,i)=>{const key=name+':'+i,done=s.duties[key];return '<div class="duty"><b>'+esc(task)+'</b>'+(done?'<p class="small">✓ '+esc(done.note)+' · '+esc(done.by)+'</p>':'<label>What did you do?<input data-duty-note="'+esc(key)+'" maxlength="300" placeholder="One short work note"></label><button class="quiet" data-duty="'+esc(key)+'">Save task note</button>')+'</div>';}).join('')+'</section>';}).join('')+'</div>'+(CAFE||PET?'<section class="card pink"><h3>Menu prices & advertising</h3><p class="small">'+(CAFE?'Practice selling prices are editable because the original packet’s price table was blank.':'The pet-care price starts at the team’s updated $40 decision.')+'</p>'+(CAFE?'<div class="grid">'+MENU.map(m=>'<label>'+m.icon+' '+m.name+'<input data-price="'+m.id+'" type="number" min="0" max="1000" step="0.25" value="'+s.prices[m.id]+'"></label>').join('')+'</div>':'<label>Pet care per pet<input id="pet-price" type="number" min="0" step="1" value="'+s.petPrice+'"></label>')+'<button data-do="save-prices">Save prices</button><label>Customer advertisement<textarea id="ad-message" maxlength="180" placeholder="Write your shop’s message.">'+esc(s.ad)+'</textarea></label><button class="accent" data-do="save-ad">📣 Display our customer message</button></section>':'');}
